def evaluate(expr: str) -> float:
    if not isinstance(expr, str):
        raise ValueError('expression must be a string')

    s = expr
    n = len(s)
    i = 0

    def skip_ws():
        nonlocal i
        while i < n and s[i].isspace():
            i += 1

    def fail(msg):
        raise ValueError(msg)

    def parse_number():
        skip_ws()
        start = i
        digits = 0
        while i < n and s[i].isdigit():
            i += 1
            digits += 1
        if i < n and s[i] == '.':
            i += 1
            while i < n and s[i].isdigit():
                i += 1
                digits += 1
        if digits == 0:
            fail('expected a number')
        return float(s[start:i])

    def parse_primary():
        skip_ws()
        if i < n and s[i] == '(':
            i += 1
            value = parse_expression()
            skip_ws()
            if i >= n or s[i] != ')':
                fail('expected )')
            i += 1
            return value
        return parse_number()

    def parse_factor():
        skip_ws()
        if i < n and (s[i] == '+' or s[i] == '-'):
            op = s[i]
            i += 1
            value = parse_factor()
            return value if op == '+' else -value
        return parse_power()

    def parse_power():
        base = parse_primary()
        skip_ws()
        if i + 1 < n and s[i] == '*' and s[i + 1] == '*':
            i += 2
            exponent = parse_factor()
            return base ** exponent
        return base

    def parse_term():
        value = parse_factor()
        while True:
            skip_ws()
            if i < n and (s[i] == '*' or s[i] == '/'):
                op = s[i]
                i += 1
                right = parse_factor()
                value = value * right if op == '*' else value / right
            else:
                return value

    def parse_expression():
        value = parse_term()
        while True:
            skip_ws()
            if i < n and (s[i] == '+' or s[i] == '-'):
                op = s[i]
                i += 1
                right = parse_term()
                value = value + right if op == '+' else value - right
            else:
                return value

    result = parse_expression()
    skip_ws()
    if i != n:
        fail('unexpected trailing input')
    return float(result)
