def diff_lines(a, b):
    n, m = len(a), len(b)

    # dp[i][j] = length of LCS of a[:i] and b[:j]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        ai = a[i - 1]
        row, prev = dp[i], dp[i - 1]
        for j in range(1, m + 1):
            if ai == b[j - 1]:
                row[j] = prev[j - 1] + 1
            else:
                v = prev[j]
                if row[j - 1] > v:
                    v = row[j - 1]
                row[j] = v

    # Backtrack from (n, m) to (0, 0)
    result = []
    i, j = n, m
    while i > 0 or j > 0:
        if i > 0 and j > 0 and a[i - 1] == b[j - 1]:
            result.append(('=', a[i - 1]))
            i -= 1
            j -= 1
        elif i > 0 and (j == 0 or dp[i - 1][j] >= dp[i][j - 1]):
            result.append(('-', a[i - 1]))
            i -= 1
        else:
            result.append(('+', b[j - 1]))
            j -= 1

    result.reverse()
    return result
