            pos = events[i][0]
            delta = 0
            while i < n and events[i][0] == pos:
                delta += events[i][1]
                i += 1
            current += delta
            if current > max_active:
                max_active = current

        if max_active >= 2:
            return False

        self.bookings.append((start, end))
        return True
